import { PokemonCard } from '../../../game/store/card/pokemon-card';
import { Stage, CardType, SuperType } from '../../../game/store/card/card-types';
import {
  StoreLike,
  State,
  ConfirmPrompt,
  GameMessage,
  pokemonHasCardType,
  ChooseCardsPrompt,
  Card,
} from '../../../game';
import { Effect } from '../../../game/store/effects/effect';
import { WAS_ATTACK_USED, MOVE_CARDS } from '../../../game/store/prefabs/prefabs';

export class Chandelure extends PokemonCard {
  public stage: Stage = Stage.STAGE_2;
  public evolvesFrom: string = 'Lampent';
  public cardType: CardType[] = [R];
  public hp: number = 140;
  public weakness = [{ type: W }];
  public retreat = [C, C];

  public attacks = [
    {
      name: 'Spirit Burner',
      cost: [R],
      damage: 10,
      damageCalculation: '+',
      text: 'Discard the top 5 cards of your deck. This attack does 60 more damage for each Pokémon you discarded in this way. Then, put any number of Fire Pokémon you discarded in this way onto your Bench.',
    },
  ];

  public set: string = 'UNM';
  public setNumber: string = '30';
  public cardImage: string = 'assets/cardback.png';
  public name: string = 'Chandelure';
  public fullName: string = 'Chandelure UNM';

  public reduceEffect(store: StoreLike, state: State, effect: Effect): State {
    // Attack 1: Spirit Burner
    if (WAS_ATTACK_USED(effect, 0, this)) {
      const player = effect.player;

      // Discard top 5 cards
      const cardsToDiscard = player.deck.cards.slice(0, 5);
      const discardedPokemon: PokemonCard[] = [];

      cardsToDiscard.forEach((card) => {
        MOVE_CARDS(store, state, player.deck, player.discard, { cards: [card], sourceCard: this });
        if (card instanceof PokemonCard) {
          discardedPokemon.push(card);
        }
      });

      // Add damage for each Pokemon discarded
      effect.damage += 60 * discardedPokemon.length;

      // Find Fire Pokemon among the discarded
      const firePokemon = discardedPokemon.filter((p) => pokemonHasCardType(p, CardType.FIRE));
      const openSlots = player.bench.filter((b) => b.cards.length === 0);

      if (firePokemon.length > 0 && openSlots.length > 0) {
        return store.prompt(
          state,
          new ConfirmPrompt(player.id, GameMessage.WANT_TO_USE_EFFECT_OF_ATTACK),
          (wantToPlace) => {
            if (!wantToPlace) {
              return state;
            }

            const max = Math.min(firePokemon.length, openSlots.length);
            const blocked: number[] = [];
            player.discard.cards.forEach((card, index) => {
              if (!firePokemon.includes(card as PokemonCard)) {
                blocked.push(index);
              }
            });

            return store.prompt(
              state,
              new ChooseCardsPrompt(
                player,
                GameMessage.CHOOSE_CARD_TO_PUT_ONTO_BENCH,
                player.discard,
                { superType: SuperType.POKEMON },
                { min: 0, max, allowCancel: false, blocked },
              ),
              (selected) => {
                const cards: Card[] = selected || [];
                cards.forEach((card, index) => {
                  MOVE_CARDS(store, state, player.discard, openSlots[index], {
                    cards: [card],
                    sourceCard: this,
                  });
                  openSlots[index].pokemonPlayedTurn = state.turn;
                });
              },
            );
          },
        );
      }
    }

    return state;
  }
}
